public class Foo {
    void m() {
        for (double d = 0.0; d < 1.0; d += 0.1) {
            System.out.println(d);
        }
    }
}

public class Foo {
    void m() {
        for (float f = 0f; f < 1f; f += 0.1f) {
            System.out.println(f);
        }
    }
}

public class Foo {
    void m() {
        double d;
        for (d = 0.0; d < 1.0; d += 0.1) {
            System.out.println(d);
        }
    }
}

public class Foo {
    void m(double[] values) {
        for (int i = 0; i < 10; i++) {
            double x = i * 0.1;
            System.out.println(x);
        }
        for (double v : values) {
            System.out.println(v);
        }
    }
}
